import styled from '@emotion/styled';
import { theme } from 'theme';

const PRIMARY_BLUE = '#006EDB';

export const DDT_COLORS = {
  text: {
    primary: theme.colors.txt.default,
    secondary: theme.colors.txt.secondary,
    positive: theme.colors.green.high,
    negative: theme.colors.red.high,
    neutral: theme.colors.txt.secondary,
  },
  background: {
    white: '#FFFFFF',
    groupHeader: '#FAFAFA',
    accent: '#E0F3FF',
    level1: '#F6FBFF',
    level2: '#EEF6FA',
    level3: '#E6F1F5',
    level4: '#D7E4EA',
    levelDeep: '#D7E4EA',
  },
  border: {
    row: 'rgba(20, 20, 20, 0.08)',
    header: 'rgba(20, 20, 20, 0.16)',
    group: 'rgba(20, 20, 20, 0.16)',
    table: 'rgba(20, 20, 20, 0.16)',
  },
  chevron: PRIMARY_BLUE,
} as const;

export const DDT_RADIUS = {
  table: '12px',
} as const;

export const DDT_SPACING = {
  rowHeight: '48px',
  headerGroupHeight: '44px',
  headerSubHeight: '44px',
  axisDefaultWidth: '200px',
  indentStep: 16,
} as const;

export const DDTCard = styled.div({
  backgroundColor: DDT_COLORS.background.white,
  border: `1px solid ${DDT_COLORS.border.table}`,
  borderRadius: DDT_RADIUS.table,
  overflow: 'hidden',
  width: '100%',
  boxSizing: 'border-box',
});

export const DDTTable = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  marginTop: '16px',
  borderTop: `1px solid ${DDT_COLORS.border.header}`,
});

export const DDTBody = styled.div({
  display: 'flex',
  flexDirection: 'column',
});
